/* The IMBE 7200x4400 tables (imbe_tables.c, generated by py/gen_imbe_tables.py from mbelib's) and the synthesis
   tables. */
#ifndef IMBE_TABLES_H
#define IMBE_TABLES_H

/* The tables of the hot loops: the firmware can put them into RAM (-DIMBE_RAM_DATA=__attribute__((section(...)))) */
#ifndef IMBE_RAM_DATA
#define IMBE_RAM_DATA
#endif

/* parameters, indexed by b0 (0..207) or by L - 9 (L 9..56) */
extern const unsigned int ImbeW0q[208];        /* w0, 2^32 = 2 pi */
extern const unsigned char ImbeL[208];
extern const int ImbeB2Q12[64];                /* G1 */
extern const unsigned char ImbeBaBits[48][5];  /* bits of b3..b7 */
extern const int ImbeBaStepQ24[48][5];         /* their steps */
extern const unsigned char ImbeHoba[48][50];   /* bits of b8..b(L+1) */
extern const unsigned char ImbeBo[48][79][2];  /* bit order: (b index, bit) */
extern const unsigned char ImbeBlockLen[48][6]; /* block lengths */
extern const int ImbeQsSdQ16[10][9];           /* quantstep[Bm - 1] x standdev[k - 2] */

/* synthesis */
extern const short ImbeCosQ12[1025];
extern const short ImbeWsQ15[321];
extern const short ImbeSqrtWsQ15[321];
extern const int ImbePhaseDispQ32[58];
extern const short ImbeLog2Q12[257];
extern const unsigned short ImbeExp2Q15[257];

#endif
